logics.src:
// Namespace this callee's reply and clear the shared envelope, so the
// next api_rpc in this task cannot be read as this one's verdict.
// ES5 only. Corezoid does NOT interpolate {{...}} in a Code node's src.
data.order_result = String(data.result || "");
data.order_code = String(data.code || "");
data.order_status = data.status || "";

data.result = "";
data.code = "";

// Branch on the NAMESPACED keys, never on the bare {{result}}/{{code}}.
if (data.order_result === "success" || data.order_code === "200") {
    data.outcome = "success";
    data.text_id = "orderStatusDone";
} else if (data.order_result === "error" || data.order_result === "") {
    data.outcome = "error";
    data.text_id = "serviceError";
} else {
    data.outcome = "alternate";
    data.text_id = "orderStatusNotFound";
}
